def is_undulating(n):
    str_n = str(n)
    if len(str_n) < 3:
        return False
    first_digit, second_digit = str_n[0], str_n[1]
    if first_digit == second_digit:
        return False
    for i in range(2, len(str_n)):
        if i % 2 == 0 and str_n[i] != first_digit:
            return False
        elif i % 2 != 0 and str_n[i] != second_digit:
            return False
    return True

