def get_total_number_of_sequences(m, n):
    """
    This function calculates the number of possible sequences of length n, where each element is a positive integer
    and is greater than or equal to twice the previous element but less than or equal to m.
    """
    def count_sequences(current_m, length_left, prev_value):
        if length_left == 0:
            return 1
        count = 0
        for i in range(2 * prev_value, current_m + 1):
            count += count_sequences(current_m, length_left - 1, i)
        return count

    if m < 2 * n:
        return 0
    return count_sequences(m, n, 1) - 1

# Corrected function based on the problem statement
def get_total_number_of_sequences(m, n):
    def count_sequences(current_m, length_left, prev_value):
        if length_left == 0:
            return 1
        count = 0
        for i in range(max(2 * prev_value, prev_value + 1), current_m + 1):
            count += count_sequences(current_m, length_left - 1, i)
        return count

    if m < 2 * n:
        return 0
    return count_sequences(m, n, 1)

# Test cases
