def newman_prime(n):
    """
    This function calculates the nth Newman-Shanks-Williams prime number.
    The sequence is defined as follows:
    - P_1 = 1, P_2 = 1
    - For n > 2, P_n = P_{n-1} + 2 * P_{n-2}
    """
    if n == 1 or n == 2:
        return 1
    a, b = 1, 1
    for i in range(3, n+1):
        a, b = b, a + 2*b
    return b

