def get_max_sum(n: int) -> int:
    """
    Calculate the maximum sum possible by using the given equation recursively.

    Args:
    n (int): The input integer.

    Returns:
    int: The maximum sum possible.
    """
    # Base case: if n is less than 2, return n
    if n < 2:
        return n
    # Recursive case: calculate the max sum using the given equation
    return max((get_max_sum(n // 2) + get_max_sum(n // 3) + get_max_sum(n // 4) + get_max_sum(n // 5)), n)

# Correct implementation with memoization to optimize repeated calculations
def optimized_get_max_sum(n: int) -> int:
