    def helper(x):
        if x in memo:
            return memo[x]
        if x < 2:
            result = x
        else:
            result = max((helper(x // 2) + helper(x // 3) + helper(x // 4) + helper(x // 5)), x)
        memo[x] = result
        return result

    return helper(n)

