def combinations_list(lst):
    from itertools import chain, combinations

    def all_combinations(elements):
        return list(chain.from_iterable(combinations(elements, r) for r in range(len(elements)+1)))

    return all_combinations(lst)

# Testing the function with the provided data points
print(combinations_list(['orange', 'red', 'green', 'blue']))
print(combinations_list(['red', 'green', 'blue', 'white', 'black', 'orange']))
print(combinations_list(['red', 'green', 'black', 'orange']))
```

