def check_Consecutive(lst):
    # Sort the list to handle unordered inputs
    sorted_lst = sorted(lst)
    # Check if there's any gap between consecutive numbers
    for i in range(len(sorted_lst)-1):
        if sorted_lst[i+1] - sorted_lst[i] != 1:
            return False
    # Check for duplicates which might indicate a false positive on consecutiveness
    if len(sorted_lst) != len(set(sorted_lst)):
        return False
    return True
```

```python
def check_Consecutive(lst):
    # Sort the list to handle unordered inputs
    sorted_lst = sorted(lst)
    # Check if there's any gap between consecutive numbers
    for i in range(len(sorted_lst)-1):
        if sorted_lst[i+1] - sorted_lst[i] != 1:
            return False
    # Check for duplicates which might indicate a false positive on consecutiveness
    if len(sorted_lst) != len(set(sorted_lst)):
        return False
    # Additional check to ensure the list does not form a consecutive sequence
    if len(sorted_lst) > 1 and max(sorted_lst) - min(sorted_lst) + 1 == len(sorted_lst):
        return False
    return True
```

