```python
def first_Digit(n):
    # Convert the number to a string to easily access the first character
    # Then convert that character back to an integer and return it
    return int(str(n)[0])
```

```python
def first_Digit(n):
    # Convert the number to a string to access individual digits
    str_n = str(n)
    # Iterate through the string to find and return the first non-zero digit
    for digit in str_n:
        if digit != '0':
            return int(digit)
```

```python
def first_Digit(n):
    # Convert the number to a string to find the first non-zero digit
    str_n = str(n)
    # Iterate through the string to find the first non-zero digit
    for digit in str_n:
        if digit != '0':
            return int(digit)
    # If the loop completes without returning, the number is 0
    return 0
